            shifted = (ord(char) - base + shift) % 26 + base
            result += chr(shifted)
        else:
            result += char
    return result

def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for ch in text:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            idx = ord(ch) - base
            new_idx = (idx + shift) % 26
            result.append(chr(base + new_idx))
        else:
            result.append(ch)
    return ''.join(result)

